package com.cache.client

import java.util.concurrent.{ConcurrentLinkedQueue, atomic}
import java.util.concurrent.atomic.{AtomicInteger, AtomicReference}
import scala.util.{Try, Success, Failure}
import scala.collection.mutable

case class CacheNode(host: String, port: Int, weight: Int = 1)

trait Connection {
  def get(key: String): Option[String]
  def set(key: String, value: String, ttl: Int): Boolean
  def isAlive: Boolean
  def close(): Unit
}

class TcpConnection(node: CacheNode) extends Connection {
  @volatile private var closed = false
  override def get(key: String): Option[String] = {
    if (closed) throw new IllegalStateException("Connection closed")
    // Simulated network call
    Some(s"value_for_$key")
  }
  override def set(key: String, value: String, ttl: Int): Boolean = !closed
  override def isAlive: Boolean = !closed
  override def close(): Unit = { closed = true }
}

class ConnectionPool(node: CacheNode, maxSize: Int = 8) {
  private val pool = new ConcurrentLinkedQueue[Connection]()
  private val activeCount = new AtomicInteger(0)
  private val nodeRef = new AtomicReference[CacheNode](node)

  def borrow(): Connection = {
    val conn = pool.poll()
    if (conn != null && conn.isAlive) {
      conn
    } else {
      if (conn != null) activeCount.decrementAndGet()
      createConnection()
    }
  }

  def release(conn: Connection): Unit = {
    if (conn.isAlive && pool.size() < maxSize) {
      pool.offer(conn)
    } else {
      conn.close()
      activeCount.decrementAndGet()
    }
  }

  private def createConnection(): Connection = {
    activeCount.incrementAndGet()
    new TcpConnection(nodeRef.get())
  }

  def drain(): Unit = {
    var conn = pool.poll()
    while (conn != null) {
      conn.close()
      activeCount.decrementAndGet()
      conn = pool.poll()
    }
  }

  def currentNode: CacheNode = nodeRef.get()
  def updateNode(newNode: CacheNode): Unit = nodeRef.set(newNode)
}

class ConsistentHashRing(nodes: Seq[CacheNode], virtualNodes: Int = 150) {
  private val ring = new java.util.TreeMap[Long, CacheNode]()

  nodes.foreach(addNode)

  def addNode(node: CacheNode): Unit = {
    (0 until virtualNodes * node.weight).foreach { i =>
      val hash = computeHash(s"${node.host}:${node.port}#$i")
      ring.put(hash, node)
    }
  }

  def removeNode(node: CacheNode): Unit = {
    (0 until virtualNodes * node.weight).foreach { i =>
      val hash = computeHash(s"${node.host}:${node.port}#$i")
      ring.remove(hash)
    }
  }

  def getNode(key: String): Option[CacheNode] = {
    if (ring.isEmpty) return None
    val hash = computeHash(key)
    val entry = ring.ceilingEntry(hash)
    if (entry != null) Some(entry.getValue)
    else Some(ring.firstEntry().getValue)
  }

  private def computeHash(key: String): Long = {
    val md = java.security.MessageDigest.getInstance("MD5")
    val digest = md.digest(key.getBytes("UTF-8"))
    ((digest(3).toLong & 0xFF) << 24) |
      ((digest(2).toLong & 0xFF) << 16) |
      ((digest(1).toLong & 0xFF) << 8) |
      (digest(0).toLong & 0xFF)
  }
}

class DistributedCacheClient(initialNodes: Seq[CacheNode]) {
  private val pools = new mutable.HashMap[String, ConnectionPool]()
  private val hashRing = new ConsistentHashRing(initialNodes)
  private val failureCounters = new mutable.HashMap[String, AtomicInteger]()
  private val failureThreshold = 3
  @volatile private var healthCheckRunning = true

  initialNodes.foreach { node =>
    val key = nodeKey(node)
    pools.put(key, new ConnectionPool(node))
    failureCounters.put(key, new AtomicInteger(0))
  }

  def get(key: String): Option[String] = {
    hashRing.getNode(key) match {
      case None => None
      case Some(node) =>
        pools.get(nodeKey(node)) match {
          case Some(p) =>
            val conn = p.borrow()
            try {
              val result = conn.get(key)
              failureCounters.get(nodeKey(node)).foreach(_.set(0))
              result
            } catch {
              case e: Exception =>
                handleFailure(node)
                None
            } finally {
              p.release(conn)
            }
          case None =>
            None
        }
    }
  }

  def set(key: String, value: String, ttl: Int = 3600): Boolean = {
    hashRing.getNode(key) match {
      case None => false
      case Some(node) =>
        pools.get(nodeKey(node)) match {
          case Some(p) =>
            val conn = p.borrow()
            try {
              val result = conn.set(key, value, ttl)
              failureCounters.get(nodeKey(node)).foreach(_.set(0))
              result
            } catch {
              case e: Exception =>
                handleFailure(node)
                false
            } finally {
              p.release(conn)
            }
          case None =>
            false
        }
    }
  }

  private def handleFailure(node: CacheNode): Unit = {
    val key = nodeKey(node)
    failureCounters.get(key).foreach { counter =>
      if (counter.incrementAndGet() >= failureThreshold) {
        removeNode(node)
      }
    }
  }

  def removeNode(node: CacheNode): Unit = {
    val key = nodeKey(node)
    hashRing.removeNode(node)
    pools.get(key).foreach(_.drain())
    pools.remove(key)
    failureCounters.remove(key)
  }

  private def nodeKey(node: CacheNode): String = s"${node.host}:${node.port}"

  def shutdown(): Unit = {
    healthCheckRunning = false
    pools.values.foreach(_.drain())
    pools.clear()
  }
}
